@php $card=$item['row'];$overdue=!$card->completed_at && $card->due_date?->isBefore(today()); @endphp
<article class="folder-task-card" x-data="{title:@js(mb_strtolower($item['label'])),state:@js($card->completed_at?'done':'open'),overdue:@js((bool)$overdue)}" x-show="{{ $taskVisible }}"><div class="folder-panel-head"><span class="notes-priority">{{ ucfirst($card->priority) }}</span><span class="notes-hint">{{ $card->completed_at?'Done':($overdue?'Overdue':($card->progress>0?'In progress':'To do')) }}</span></div><a href="{{ $item['url'] }}"><h3>{{ $item['label'] }}</h3></a><p class="notes-hint">{{ \Illuminate\Support\Str::limit($card->description,140) }}</p><div class="folder-progress"><span style="width:{{ max(0,min(100,(int)$card->progress)) }}%"></span></div><div class="folder-task-meta"><span><i class="fas fa-calendar"></i> {{ $card->due_date?->format('d M')??'No deadline' }}</span><span><i class="fas fa-list-check"></i> {{ $card->subtasks->where('completed',true)->count() }}/{{ $card->subtasks->count() }}</span></div><p class="notes-hint">{{ $card->assignees->pluck('name')->join(', ')?:'Unassigned' }} · {{ $card->board?->name }}</p>@canInWorkspace('tasks.edit')<form method="post" action="{{ route('user.ai.folders.complete',[$project,$card]) }}" class="mt-3">@csrf<input type="hidden" name="action" value="{{ $card->completed_at?'reopen':'complete' }}"><button class="form-chip">{{ $card->completed_at?'Reopen task':'Mark complete' }}</button></form>@endcanInWorkspace</article>
